import type { BookOutput as Book } from "./book.ts";

/** The slice of an MCP client writeBook needs: one `call(tool, args)` round trip. */
export type McpClient = {
  call(tool: string, args: Record<string, unknown>): Promise<unknown>;
};

/** One place where the read-back disagrees with what was sent. */
export type BookDiff = { path: string; sent: unknown; got: unknown };

export type WriteBookResult = {
  ok: boolean;
  attempts: number;
  diffs: BookDiff[];
};

/** Numbers that differ by no more than this count as equal. */
const TOLERANCE = 0.005;

export const WRITE_TOOL = "edit_table_blocks";
export const READ_TOOL = "inspect_table_blocks";

const isRecord = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v);

const isAbsent = (v: unknown): boolean => v === null || v === undefined;

const sameScalar = (sent: unknown, got: unknown): boolean => {
  if (typeof sent === "number" && typeof got === "number") {
    if (Number.isNaN(sent) && Number.isNaN(got)) return true;
    return Math.abs(sent - got) <= TOLERANCE;
  }
  if (isAbsent(sent) || isAbsent(got)) return isAbsent(sent) && isAbsent(got);
  return sent === got;
};

function collect(path: string, sent: unknown, got: unknown, out: BookDiff[]): void {
  if (Array.isArray(sent) || Array.isArray(got)) {
    if (!Array.isArray(sent) || !Array.isArray(got)) {
      out.push({ path, sent, got });
      return;
    }
    const length = Math.max(sent.length, got.length);
    for (let i = 0; i < length; i++) {
      collect(`${path}[${i}]`, sent[i], got[i], out);
    }
    return;
  }
  if (isRecord(sent) && isRecord(got)) {
    const keys = Object.keys(sent);
    for (const key of Object.keys(got)) if (!(key in sent)) keys.push(key);
    for (const key of keys) {
      collect(path === "" ? key : `${path}.${key}`, sent[key], got[key], out);
    }
    return;
  }
  if (!sameScalar(sent, got)) out.push({ path, sent, got });
}

/** Every path where the read-back differs from what was sent. Numbers compare within 0.005. */
export function diffBook(sent: Book, readback: Book): BookDiff[] {
  const diffs: BookDiff[] = [];
  collect("", sent, readback, diffs);
  return diffs;
}

/** The read-back arrives as a Book-shaped object at `result.book`; absent means empty. */
const readbackOf = (result: unknown): Book =>
  isRecord(result) && isRecord(result.book) ? (result.book as Book) : ({} as Book);

/**
 * Write the book through the cfo.ai MCP, then read it back and diff it.
 * On a mismatch the write is retried (`opts.retries`, default 1). Client errors count
 * as an attempt and are never thrown; they leave `diffs` empty for that attempt.
 */
export async function writeBook(
  book: Book,
  client: McpClient,
  opts: { retries?: number } = {},
): Promise<WriteBookResult> {
  const budget = Math.max(0, Math.floor(opts.retries ?? 1)) + 1;
  let attempts = 0;
  let diffs: BookDiff[] = [];

  for (let i = 0; i < budget; i++) {
    attempts++;
    try {
      await client.call(WRITE_TOOL, { book });
      const result = await client.call(READ_TOOL, {});
      diffs = diffBook(book, readbackOf(result));
      if (diffs.length === 0) return { ok: true, attempts, diffs: [] };
    } catch {
      diffs = [];
    }
  }

  return { ok: false, attempts, diffs };
}

import { expect, test } from "bun:test";
import { buildBook, type BookOutput } from "../src/cfo/book.ts";
import { diffBook, writeBook } from "../src/cfo/mcp.ts";

type Call = { tool: string; args: Record<string, unknown> };

/** The book we actually send: two setups plus the promoted one that drives the scenario. */
const book = (): BookOutput =>
  buildBook({
    periodDays: 15,
    setups: [
      { id: "a", label: "A", costUsd: 30, sessions: 10, survivingChanges: 6, unattendedShare: 0.5555 },
      { id: "b", label: "B", costUsd: null, sessions: 4, survivingChanges: 0, unattendedShare: 0 },
    ],
    promoted: "a",
    assumptions: { engineerMonthlyLoadedUsd: 15000, scaleSessionsPerWeek: 70 },
  });

/** A client that serves writes from `ok` and read-backs from `reads`, one per inspect. */
const client = (
  reads: unknown[],
  calls: Call[] = [],
): { call(tool: string, args: Record<string, unknown>): Promise<unknown> } => {
  let i = 0;
  return {
    async call(tool, args) {
      calls.push({ tool, args });
      if (tool === "edit_table_blocks") return { ok: true };
      if (tool === "inspect_table_blocks") return reads[Math.min(i++, reads.length - 1)];
      throw new Error(`unexpected tool ${tool}`);
    },
  };
};

test("matching read-back writes once and reads once", async () => {
  const sent = book();
  const calls: Call[] = [];
  const res = await writeBook(sent, client([{ book: sent }], calls));

  expect(res).toEqual({ ok: true, attempts: 1, diffs: [] });
  expect(calls.map((c) => c.tool)).toEqual(["edit_table_blocks", "inspect_table_blocks"]);
  expect(calls[0]?.args).toEqual({ book: sent });
});

test("numbers just outside the tolerance are a mismatch", async () => {
  const sent = book();
  const readback = book();
  readback.scenario.scaleMonthlyUsd = sent.scenario.scaleMonthlyUsd! + 0.006;

  const res = await writeBook(sent, client([{ book: readback }]));

  expect(res.ok).toBe(false);
  expect(res.diffs).toEqual([
    {
      path: "scenario.scaleMonthlyUsd",
      sent: sent.scenario.scaleMonthlyUsd,
      got: sent.scenario.scaleMonthlyUsd! + 0.006,
    },
  ]);
});

test("a number within the tolerance is not a mismatch", () => {
  expect(diffBook(book(), book())).toEqual([]);
  const nudged = book();
  nudged.department[0]!.costPerSurvivingChangeUsd = nudged.department[0]!.costPerSurvivingChangeUsd! + 0.005;
  expect(diffBook(book(), nudged)).toEqual([]);
});

test("a missing read-back is empty, so it retries once and can still succeed", async () => {
  const sent = { value: 1.005 } as unknown as BookOutput;
  const calls: Call[] = [];
  const res = await writeBook(sent, client([{}, { book: sent }], calls));

  expect(res).toEqual({ ok: true, attempts: 2, diffs: [] });
  expect(calls.map((c) => c.tool)).toEqual([
    "edit_table_blocks",
    "inspect_table_blocks",
    "edit_table_blocks",
    "inspect_table_blocks",
  ]);
});

test("a persistent mismatch returns the diffs after the default retry", async () => {
  const sent = { value: 1.005 } as unknown as BookOutput;
  const calls: Call[] = [];
  const res = await writeBook(sent, client([{ book: { value: 2.005 } }], calls));

  expect(res.ok).toBe(false);
  expect(res.attempts).toBe(2);
  expect(res.diffs).toEqual([{ path: "value", sent: 1.005, got: 2.005 }]);
  expect(calls.filter((c) => c.tool === "edit_table_blocks")).toHaveLength(2);
});

test("opts.retries sets the number of extra attempts", async () => {
  const sent = { value: 1 } as unknown as BookOutput;
  const calls: Call[] = [];
  const res = await writeBook(sent, client([{ book: { value: 2 } }], calls), { retries: 2 });

  expect(res.ok).toBe(false);
  expect(res.attempts).toBe(3);
  expect(calls.filter((c) => c.tool === "edit_table_blocks")).toHaveLength(3);
  expect(calls.filter((c) => c.tool === "inspect_table_blocks")).toHaveLength(3);
});

test("a client error is an attempt, not a throw", async () => {
  let calls = 0;
  const failing = {
    async call(): Promise<unknown> {
      calls++;
      throw new Error("client unavailable");
    },
  };

  const res = await writeBook(book(), failing, { retries: 0 });

  expect(res).toEqual({ ok: false, attempts: 1, diffs: [] });
  expect(calls).toBe(1);
});

test("a transient write error is retried and can still succeed", async () => {
  const sent = book();
  const calls: Call[] = [];
  let writes = 0;
  const flaky = {
    async call(tool: string, args: Record<string, unknown>): Promise<unknown> {
      calls.push({ tool, args });
      if (tool === "edit_table_blocks") {
        if (writes++ === 0) throw new Error("429");
        return { ok: true };
      }
      return { book: sent };
    },
  };

  const res = await writeBook(sent, flaky);

  expect(res).toEqual({ ok: true, attempts: 2, diffs: [] });
  expect(calls.map((c) => c.tool)).toEqual(["edit_table_blocks", "edit_table_blocks", "inspect_table_blocks"]);
});

test("a read error counts as an attempt", async () => {
  const reads = { async call(tool: string): Promise<unknown> {
    if (tool === "edit_table_blocks") return { ok: true };
    throw new Error("inspect failed");
  } };

  const res = await writeBook(book(), reads, { retries: 0 });

  expect(res).toEqual({ ok: false, attempts: 1, diffs: [] });
});

test("diffBook reports nested paths, nulls, lengths and extra keys", () => {
  const sent = book();
  const readback = book();
  readback.department[0]!.monthlySpendUsd = null;
  readback.department[1]!.unattendedPct = 12;
  readback.department.pop();
  readback.assumptions = { ...readback.assumptions, engineerMonthlyLoadedUsd: 14000 };
  (readback as Record<string, unknown>).extra = true;

  const paths = diffBook(sent, readback).map((d) => d.path);

  expect(paths).toContain("department[0].monthlySpendUsd");
  expect(paths).toContain("department[1].unattendedPct");
  expect(paths).toContain("department[2].setup");
  expect(paths).toContain("assumptions.engineerMonthlyLoadedUsd");
  expect(paths).toContain("extra");
  expect(diffBook(sent, readback)[0]?.sent).toBe(sent.department[0]?.monthlySpendUsd);
});

test("diffBook treats absent and null as the same, and catches array-vs-scalar", () => {
  expect(diffBook({ department: null } as unknown as BookOutput, {} as BookOutput)).toEqual([]);
  expect(diffBook({ department: [] } as unknown as BookOutput, { department: 1 } as unknown as BookOutput)).toEqual([
    { path: "department", sent: [], got: 1 },
  ]);
});

